{
  "object": "ბიურეტით ტიტრაციის მოწყობილობა",
  "parts": [
    {
      "id": "funnel",
      "label": "ბიურეტში ჩასმული ძაბრი",
      "box": [425, 2, 568, 125]
    },
    {
      "id": "burette_tube",
      "label": "ბიურეტის მილი",
      "box": [474, 77, 514, 380]
    },
    {
      "id": "burette_stopcock",
      "label": "ბიურეტის ონკანი ლურჯი სახელურით",
      "box": [442, 368, 555, 415]
    },
    {
      "id": "conical_flask",
      "label": "კონუსური კოლბა",
      "box": [400, 447, 579, 606]
    },
    {
      "id": "dropper_bottle",
      "label": "საწვეთურიანი ბოთლი უცნობი შიგთავსით",
      "box": [283, 473, 360, 606]
    },
    {
      "id": "white_tile",
      "label": "თეთრი ფილა კოლბის ქვეშ",
      "box": [314, 577, 637, 629]
    }
  ],
  "steps": [
    {
      "title": "შეავსე ბიურეტი",
      "text": "ონკანი დახურულია? ძაბრით ჩაასხი ტიტრანტი ნულოვან ნიშნულზე ოდნავ მაღლა.",
      "focus": ["funnel", "burette_tube", "burette_stopcock"],
      "avoid": [],
      "markers": [
        {
          "part": "funnel",
          "label": "ძაბრი",
          "tone": "brand"
        },
        {
          "part": "burette_stopcock",
          "label": "დახურული მდგომარეობა დაუდასტურებელია",
          "tone": "neutral"
        }
      ],
      "arrows": [],
      "tools": [],
      "warn": "ფოტოდან ვერ დასტურდება ონკანის დახურული მდგომარეობა, ნულოვანი ნიშნულის მდებარეობა ან ტიტრანტის ვინაობა. შევსების მითითებული დონე ფოტოთი დადასტურებული არ არის. ეს კვლევითი აღწერაა და არა პროფესიული რჩევა."
    },
    {
      "title": "მოხსენი ძაბრი",
      "text": "ძაბრი ტიტრაციამდე აუცილებლად მოხსენი. მისგან ჩამოსული წვეთები მოცულობას გააფუჭებს.",
      "focus": ["funnel"],
      "avoid": [],
      "markers": [
        {
          "part": "funnel",
          "label": "მოსახსნელი ძაბრი",
          "tone": "brand"
        }
      ],
      "arrows": [
        {
          "part": "funnel",
          "type": "move",
          "dir": "up"
        }
      ],
      "tools": [],
      "warn": null
    },
    {
      "title": "წაიკითხე საწყისი მოცულობა",
      "text": "თვალი სითხის დონეზე დაიჭირე და წაიკითხე მენისკის ქვედა კიდე. ჩაიწერე ჟურნალში.",
      "focus": [],
      "avoid": [],
      "markers": [],
      "arrows": [],
      "tools": ["ჟურნალი", "კალამი"],
      "warn": "მენისკის ქვედა კიდე და სკალის რიცხვები საიმედოდ არ განირჩევა, ამიტომ წაკითხვის ზუსტი ადგილი არ არის მონიშნული. საწყისი მოცულობა ფოტოდან ვერ განისაზღვრება; ჟურნალი და კალამიც არ ჩანს."
    },
    {
      "title": "დაამატე ინდიკატორი",
      "text": "კოლბაში ჩააწვეთე 2–3 წვეთი ფენოლფთალეინი და დადე თეთრ ფილაზე ონკანის ქვეშ.",
      "focus": ["conical_flask", "white_tile"],
      "avoid": [],
      "markers": [
        {
          "part": "conical_flask",
          "label": "კოლბა",
          "tone": "brand"
        },
        {
          "part": "white_tile",
          "label": "თეთრი ფილა",
          "tone": "brand"
        },
        {
          "part": "dropper_bottle",
          "label": "შიგთავსი უცნობია",
          "tone": "neutral"
        }
      ],
      "arrows": [],
      "tools": [],
      "warn": "ფენოლფთალეინის იდენტიფიცირებადი ჭურჭელი არ ჩანს; ხილული საწვეთურიანი ბოთლი ინდიკატორად არ არის მონიშნული. 2–3 წვეთი ინსტრუქციის დოზაა და ფოტოდან არ დასტურდება. კოლბა უკვე თეთრ ფილაზე დგას."
    },
    {
      "title": "ტიტრაცია",
      "text": "ონკანი ნელა გახსენი და კოლბა წრიულად ატრიალე. გაჩერდი, როცა ღია ვარდისფერი 30 წამს შენარჩუნდება.",
      "focus": ["burette_stopcock", "conical_flask"],
      "avoid": [],
      "markers": [
        {
          "part": "burette_stopcock",
          "label": "ონკანი",
          "tone": "brand"
        },
        {
          "part": "conical_flask",
          "label": "კოლბა",
          "tone": "brand"
        }
      ],
      "arrows": [],
      "tools": [],
      "warn": "ონკანის გასახსნელი ბრუნვის მიმართულება ფოტოდან ვერ დგინდება, ამიტომ ბრუნვის ისარი არ არის დამატებული. ღია ვარდისფერი საბოლოო შეფერილობა და მისი 30 წამით შენარჩუნება ამ ფოტოთი ვერ დასტურდება."
    }
  ],
  "unknown_parts": [
    "ბიურეტის ნულოვანი ნიშნული და სკალის წაკითხვადი რიცხვები მკაფიოდ არ განირჩევა.",
    "ბიურეტში მენისკის ქვედა კიდის ზუსტი მდებარეობა საიმედოდ ვერ განისაზღვრება.",
    "ტიტრანტის იდენტიფიცირებადი ჭურჭელი არ ჩანს; სითხეების ქიმიური შემადგენლობა უცნობია.",
    "ფენოლფთალეინის იდენტიფიცირებადი ჭურჭელი არ ჩანს; ხილულ საწვეთურიან ბოთლზე შიგთავსის აღმნიშვნელი ეტიკეტი არ იკითხება.",
    "ჟურნალი და კალამი ფოტოში არ ჩანს."
  ]
}
